import 'package:flutter/material.dart';

void main()=>runApp(const AstroQuestApp());
class AstroQuestApp extends StatelessWidget{const AstroQuestApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'AstroQuest',theme:ThemeData(brightness:Brightness.dark,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF55B6FF),brightness:Brightness.dark),useMaterial3:true),home:const HomePage());}
class HomePage extends StatelessWidget{const HomePage({super.key});void start(BuildContext c,String m)=>Navigator.push(c,MaterialPageRoute(builder:(_)=>MissionPage(mission:m)));@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Spacer(),const Icon(Icons.rocket_launch,size:68,color:Color(0xFF55B6FF)),const SizedBox(height:18),const Text('ASTROQUEST',style:TextStyle(fontSize:34,fontWeight:FontWeight.w800,letterSpacing:3)),const SizedBox(height:8),const Text('Junior Astronaut Mission Trainer',style:TextStyle(fontSize:17,color:Colors.white70)),const SizedBox(height:30),_b(c,'MOON MISSION','Lunar landing & exploration',Icons.nightlight_round,()=>start(c,'Moon')),const SizedBox(height:14),_b(c,'MARS MISSION','Surface expedition simulation',Icons.public,()=>start(c,'Mars')),const Spacer(),const Center(child:Text('TEAM VARENDRA ORBIT • NASA SPACE APPS 2026',style:TextStyle(fontSize:11,color:Colors.white38)))])));Widget _b(BuildContext c,String a,String b,IconData i,VoidCallback f)=>Card(child:InkWell(onTap:f,child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[Icon(i,color:const Color(0xFF55B6FF),size:34),const SizedBox(width:16),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a,style:const TextStyle(fontWeight:FontWeight.bold)),Text(b,style:const TextStyle(color:Colors.white60))])),const Icon(Icons.chevron_right)]))));}}
class MissionPage extends StatefulWidget{final String mission;const MissionPage({super.key,required this.mission});@override State<MissionPage> createState()=>_MissionPageState();}
class _MissionPageState extends State<MissionPage>{late final List<Event> events;int index=0,score=0,oxygen=100,fuel=100,battery=100;@override void initState(){super.initState();events=widget.mission=='Moon'?moonEvents:marsEvents;}void choose(Choice x){setState((){oxygen=(oxygen+x.oxygen).clamp(0,100);fuel=(fuel+x.fuel).clamp(0,100);battery=(battery+x.battery).clamp(0,100);score+=x.score;index++;});if(index>=events.length)Future.delayed(const Duration(milliseconds:200),result);}void result(){final r=((oxygen+fuel+battery)/3).round();Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>ResultPage(mission:widget.mission,score:(score*5+r).clamp(0,100),oxygen:oxygen,fuel:fuel,battery:battery)));}@override Widget build(BuildContext c){if(index>=events.length)return const SizedBox();final e=events[index];return Scaffold(appBar:AppBar(title:Text('${widget.mission.toUpperCase()} MISSION')),body:ListView(padding:const EdgeInsets.all(18),children:[Card(child:Padding(padding:const EdgeInsets.all(14),child:Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[_r('O2',oxygen),_r('FUEL',fuel),_r('POWER',battery)]))),const SizedBox(height:18),Text('MISSION EVENT ${index+1}/${events.length}',style:const TextStyle(color:Color(0xFF55B6FF),fontWeight:FontWeight.bold)),const SizedBox(height:10),Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(e.icon,size:42,color:const Color(0xFF55B6FF)),const SizedBox(height:14),Text(e.title,style:const TextStyle(fontSize:23,fontWeight:FontWeight.bold)),const SizedBox(height:10),Text(e.description,style:const TextStyle(color:Colors.white70,fontSize:16))]))),const SizedBox(height:14),...e.choices.map((x)=>Padding(padding:const EdgeInsets.only(bottom:12),child:FilledButton(onPressed:()=>choose(x),child:Text(x.text))))]));}Widget _r(String l,int v)=>Column(children:[Text(l,style:const TextStyle(color:Colors.white54,fontSize:11)),Text('$v%',style:const TextStyle(fontWeight:FontWeight.bold))]);}
class ResultPage extends StatelessWidget{final String mission;final int score,oxygen,fuel,battery;const ResultPage({super.key,required this.mission,required this.score,required this.oxygen,required this.fuel,required this.battery});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('MISSION REPORT')),body:ListView(padding:const EdgeInsets.all(24),children:[const Icon(Icons.emoji_events,size:80,color:Color(0xFF55B6FF)),const SizedBox(height:18),Text('$mission MISSION COMPLETE',textAlign:TextAlign.center,style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:20),Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(children:[Text('$score',style:const TextStyle(fontSize:60,fontWeight:FontWeight.w800)),const Text('MISSION SCORE',style:TextStyle(color:Colors.white54)),const Divider(height:30),Text('Oxygen: $oxygen%'),Text('Fuel: $fuel%'),Text('Battery: $battery%')] ))),const SizedBox(height:22),FilledButton(onPressed:()=>Navigator.popUntil(c,(r)=>r.isFirst),child:const Text('RETURN TO MISSION HUB'))]));}
class Event{final String title,description;final IconData icon;final List<Choice> choices;const Event(this.title,this.description,this.icon,this.choices);}class Choice{final String text;final int oxygen,fuel,battery,score;const Choice(this.text,{this.oxygen=0,this.fuel=0,this.battery=0,required this.score});}
const moonEvents=[Event('Landing Guidance Alert','A navigation warning appears during lunar descent.',Icons.warning_amber_rounded,[Choice('Slow down and recalibrate navigation',oxygen:-2,fuel:-3,battery:-2,score:10),Choice('Continue at current descent rate',oxygen:-1,fuel:-1,battery:-1,score:4)]),Event('Power Fluctuation','A non-essential system is consuming extra battery power.',Icons.battery_alert,[Choice('Disable non-essential systems',battery:5,score:10),Choice('Keep all systems active',battery:-8,score:2)]),Event('Surface Route','Choose a route to the lunar exploration zone.',Icons.route,[Choice('Take the safer mapped route',fuel:-4,battery:-2,score:10),Choice('Take the shorter unknown route',fuel:-2,battery:-5,score:4)])];
const marsEvents=[Event('Dust Storm Warning','A regional dust storm is approaching the exploration zone.',Icons.cloud,[Choice('Return to habitat and secure equipment',oxygen:-3,fuel:-2,battery:-2,score:10),Choice('Continue exploration',oxygen:-2,fuel:-1,battery:-6,score:3)]),Event('Communication Delay','Direct communication with mission control is temporarily unavailable.',Icons.signal_wifi_statusbar_null,[Choice('Follow the pre-approved contingency plan',oxygen:-1,fuel:-1,battery:-1,score:10),Choice('Attempt repeated transmissions',oxygen:-1,battery:-5,score:3)]),Event('Sample Collection','A scientifically interesting surface sample is within reach.',Icons.science,[Choice('Collect the sample using the planned procedure',oxygen:-2,battery:-3,score:10),Choice('Collect it quickly without full procedure',oxygen:-1,battery:-1,score:4)])];
